Let $\ensuremath{\mathrm{H}}$ be a finite structure whose universe $V(\ensuremath{\mathrm{H}})$ has size strictly greater than~$1$. If each
polymorphism of $\ensuremath{\mathrm{H}}$ is essentially unary, then {\sc Surjective $\ensuremath{\mathrm{H}}$-Colouring}
is \NP-complete.
\label{thm:Chen-hauptsatz}

  Let $\ensuremath{\mathrm{H}}$ be a retract-trivial reflexive digraph with at least three vertices. Then 
\begin{enumerate}
\item $\ensuremath{\mathrm{H}}$ has no double edge;
\item $\ensuremath{\mathrm{H}}$ is strongly connected; and
\item the automorphisms of $\ensuremath{\mathrm{H}}$ are isolated vertices in  $\widehat{\ensuremath{\mathrm{H}}^{\ensuremath{\mathrm{H}}}}$. 
\end{enumerate}
\label{lem:Benoit-lemma}

If $\ensuremath{\mathrm{H}}$ is a reflexive tournament that retracts to a 
subtournament~$\ensuremath{\mathrm{H}}_0$ with Hamilton cycle~$\HC_0$, then $\mathrm{Spill}_m(\ensuremath{\mathrm{H}}[\ensuremath{\mathrm{H}}_0,\HC_0])=V(\ensuremath{\mathrm{H}})$.
\label{lem:spillage}

Let $\ensuremath{\mathrm{H}}$ be a reflexive tournament with a subtournament~$\ensuremath{\mathrm{H}}_0$ with Hamilton cycle $\HC_0$ so that $(\ensuremath{\mathrm{H}},\ensuremath{\mathrm{H}}_0)$ and $\ensuremath{\mathrm{H}}_0$ are endo-trivial and $\mathrm{Spill}_m(\ensuremath{\mathrm{H}}[\ensuremath{\mathrm{H}}_0,\HC_0]) = V(\ensuremath{\mathrm{H}})$. 
Then $\ensuremath{\mathrm{H}}$-{\sc Retraction} can be polynomially reduced to {\sc Surjective $\ensuremath{\mathrm{H}}$-Colouring}.
\label{prop:main2}

Let $\ensuremath{\mathrm{H}}$ be a finite structure so that the idempotent polymorphisms of $\ensuremath{\mathrm{H}}$ omit all Taylor operations. Then 
{\sc $\ensuremath{\mathrm{H}}$-Retraction} is \NP-complete.
\label{thm:ret-hardness}

Let $\ensuremath{\mathrm{H}}$ be a strongly connected reflexive tournament. 
Then {\sc Surjective $\ensuremath{\mathrm{H}}$-Colouring} is \NP-complete.
\label{cor:strongly-connected1}

Let $\ensuremath{\mathrm{H}}$ be a strongly connected reflexive tournament. 
Then  {\sc Surjective $\ensuremath{\mathrm{H}}$-Colouring}
is \NP-complete
even for strongly connected digraphs.
\label{cor:strongly-connected2}

Let $\ensuremath{\mathrm{H}}$ be a non-transitive reflexive tournament. Then {\sc Surjective $\ensuremath{\mathrm{H}}$-Colouring}
is \NP-complete.
\label{thm:hauptsatz}

Let $\ensuremath{\mathrm{H}}$ be a reflexive tournament. 
If $\ensuremath{\mathrm{H}}$ is transitive, then {\sc Surjective $\ensuremath{\mathrm{H}}$-Colouring}
 is in \NL; otherwise it is \NP-complete.
\label{cor:hauptsatz}

